#include <SPI.h>
#include <LoRa.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define LORA_SS 5
#define LORA_RST 14
#define LORA_DIO0 26
#define LORA_FREQ 433E6

#define TOUCH_SCL 32
#define TOUCH_SDO 33

#define OLED_SDA 21
#define OLED_SCL 22

String nodeName = "FIELD_UNIT_1";

Adafruit_SSD1306 display(128, 64, &Wire, -1);

String draft = "";
String lastSender = "-";
String lastMessage = "Ready";
String statusText = "Starting";

int pendingKey = 0;
int tapCount = 0;
bool lowerCase = false;
bool keyLatched = false;

unsigned long lastTapTime = 0;
unsigned long nextMessageId = 1;

const unsigned long tapDelay = 850;
const unsigned long ackTimeout = 1800;
const int maxAttempts = 3;

String lastReceivedSender = "";
unsigned long lastReceivedId = 0;

String getChars(int key) {
  switch (key) {
      case 1: return ".,?!1";
          case 2: return "ABC2";
              case 3: return "DEF3";
                  case 4: return "GHI4";
                      case 5: return "JKL5";
                          case 6: return "MNO6";
                              case 7: return "PQRS7";
                                  case 8: return "TUV8";
                                      case 9: return "WXYZ9";
                                          case 10: return "0";
                                              default: return "";
                                                }
                                                }

                                                int readTouchKey() {
                                                  int pressed = 0;

                                                    digitalWrite(TOUCH_SCL, HIGH);
                                                      delayMicroseconds(2);

                                                        for (int i = 1; i <= 16; i++) {
                                                            digitalWrite(TOUCH_SCL, LOW);
                                                                delayMicroseconds(5);

                                                                    if (digitalRead(TOUCH_SDO) == LOW) {
                                                                          pressed = i;
                                                                              }

                                                                                  digitalWrite(TOUCH_SCL, HIGH);
                                                                                      delayMicroseconds(5);
                                                                                        }

                                                                                          return pressed;
                                                                                          }

                                                                                          String pendingCharacter() {
                                                                                            if (pendingKey == 0) return "";

                                                                                              String chars = getChars(pendingKey);
                                                                                                if (chars.length() == 0) return "";

                                                                                                  char c = chars[(tapCount - 1) % chars.length()];

                                                                                                    if (lowerCase && c >= 'A' && c <= 'Z') {
                                                                                                        c += 'a' - 'A';
                                                                                                          }

                                                                                                            return String(c);
                                                                                                            }

                                                                                                            void showScreen() {
                                                                                                              display.clearDisplay();
                                                                                                                display.setTextSize(1);
                                                                                                                  display.setTextColor(SSD1306_WHITE);
                                                                                                                    display.setTextWrap(true);
                                                                                                                      display.setCursor(0, 0);

                                                                                                                        display.print("Device: ");
                                                                                                                          display.println(nodeName);
                                                                                                                            display.println("----------------");

                                                                                                                              display.print("From: ");
                                                                                                                                display.println(lastSender);

                                                                                                                                  display.println(lastMessage);
                                                                                                                                    display.println("----------------");

                                                                                                                                      display.print("> ");
                                                                                                                                        display.println(draft + pendingCharacter());

                                                                                                                                          display.println(statusText);
                                                                                                                                            display.display();
                                                                                                                                            }

                                                                                                                                            void finishCharacter() {
                                                                                                                                              if (pendingKey == 0) return;

                                                                                                                                                if (draft.length() < 120) {
                                                                                                                                                    draft += pendingCharacter();
                                                                                                                                                      }

                                                                                                                                                        pendingKey = 0;
                                                                                                                                                          tapCount = 0;
                                                                                                                                                          }

                                                                                                                                                          void sendAck(String recipient, unsigned long id) {
                                                                                                                                                            LoRa.idle();
                                                                                                                                                              LoRa.beginPacket();
                                                                                                                                                                LoRa.print("ACK|");
                                                                                                                                                                  LoRa.print(recipient);
                                                                                                                                                                    LoRa.print("|");
                                                                                                                                                                      LoRa.print(id);
                                                                                                                                                                        LoRa.endPacket();
                                                                                                                                                                          LoRa.receive();
                                                                                                                                                                          }

                                                                                                                                                                          void processMessage(String packet) {
                                                                                                                                                                            if (!packet.startsWith("MSG|")) return;

                                                                                                                                                                              int first = packet.indexOf('|');
                                                                                                                                                                                int second = packet.indexOf('|', first + 1);
                                                                                                                                                                                  int third = packet.indexOf('|', second + 1);

                                                                                                                                                                                    if (first < 0 || second < 0 || third < 0) return;

                                                                                                                                                                                      String sender = packet.substring(first + 1, second);
                                                                                                                                                                                        unsigned long id = packet.substring(second + 1, third).toInt();
                                                                                                                                                                                          String message = packet.substring(third + 1);

                                                                                                                                                                                            if (sender == nodeName || sender.length() == 0) return;

                                                                                                                                                                                              sendAck(sender, id);

                                                                                                                                                                                                bool duplicate = (sender == lastReceivedSender && id == lastReceivedId);

                                                                                                                                                                                                  if (!duplicate) {
                                                                                                                                                                                                      lastReceivedSender = sender;
                                                                                                                                                                                                          lastReceivedId = id;
                                                                                                                                                                                                              lastSender = sender;
                                                                                                                                                                                                                  lastMessage = message;
                                                                                                                                                                                                                      statusText = "Received + ACK";
                                                                                                                                                                                                                          showScreen();
                                                                                                                                                                                                                            }
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                            bool waitForAck(unsigned long id, unsigned long timeout) {
                                                                                                                                                                                                                              unsigned long started = millis();

                                                                                                                                                                                                                                LoRa.receive();

                                                                                                                                                                                                                                  while (millis() - started < timeout) {
                                                                                                                                                                                                                                      int packetSize = LoRa.parsePacket();

                                                                                                                                                                                                                                          if (packetSize > 0) {
                                                                                                                                                                                                                                                String packet = "";

                                                                                                                                                                                                                                                      while (LoRa.available()) {
                                                                                                                                                                                                                                                              packet += (char)LoRa.read();
                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                          if (packet.startsWith("ACK|")) {
                                                                                                                                                                                                                                                                                  int first = packet.indexOf('|');
                                                                                                                                                                                                                                                                                          int second = packet.indexOf('|', first + 1);

                                                                                                                                                                                                                                                                                                  if (first >= 0 && second > first) {
                                                                                                                                                                                                                                                                                                            String recipient = packet.substring(first + 1, second);
                                                                                                                                                                                                                                                                                                                      unsigned long ackId = packet.substring(second + 1).toInt();

                                                                                                                                                                                                                                                                                                                                if (recipient == nodeName && ackId == id) {
                                                                                                                                                                                                                                                                                                                                            LoRa.receive();
                                                                                                                                                                                                                                                                                                                                                        return true;
                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                } else {
                                                                                                                                                                                                                                                                                                                                                                                        processMessage(packet);
                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                    LoRa.receive();
                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                            delay(2);
                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                LoRa.receive();
                                                                                                                                                                                                                                                                                                                                                                                                                  return false;
                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                  void sendMessage() {
                                                                                                                                                                                                                                                                                                                                                                                                                    finishCharacter();

                                                                                                                                                                                                                                                                                                                                                                                                                      if (draft.length() == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                          statusText = "Empty message";
                                                                                                                                                                                                                                                                                                                                                                                                                              showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                      String messageToSend = draft;
                                                                                                                                                                                                                                                                                                                                                                                                                                        unsigned long id = nextMessageId++;

                                                                                                                                                                                                                                                                                                                                                                                                                                          String packet = "MSG|" + nodeName + "|" + String(id) + "|" + messageToSend;

                                                                                                                                                                                                                                                                                                                                                                                                                                            for (int attempt = 1; attempt <= maxAttempts; attempt++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                statusText = "Sending " + String(attempt) + "/3";
                                                                                                                                                                                                                                                                                                                                                                                                                                                    showScreen();

                                                                                                                                                                                                                                                                                                                                                                                                                                                        LoRa.idle();
                                                                                                                                                                                                                                                                                                                                                                                                                                                            LoRa.beginPacket();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                LoRa.print(packet);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int result = LoRa.endPacket();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        LoRa.receive();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (result == 1 && waitForAck(id, ackTimeout)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  lastSender = "You";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lastMessage = messageToSend;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              draft = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    statusText = "Delivered: ACK";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        statusText = "Waiting for ACK";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                statusText = "No ACK: failed";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  void receiveMessage() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    int packetSize = LoRa.parsePacket();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (packetSize <= 0) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        String packet = "";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          while (LoRa.available()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              packet += (char)LoRa.read();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  processMessage(packet);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    LoRa.receive();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    void handleTouchKey(int key) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      unsigned long now = millis();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (key == 12) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (pendingKey != 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  pendingKey = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tapCount = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } else if (draft.length() > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  draft.remove(draft.length() - 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          statusText = "Backspace";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (key == 16) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          sendMessage();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (key == 15) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      finishCharacter();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (draft.length() < 120) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                draft += ' ';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        statusText = "Space";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (key == 11) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        finishCharacter();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            lowerCase = !lowerCase;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                statusText = lowerCase ? "Lowercase" : "Uppercase";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (key == 13) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                draft = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pendingKey = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tapCount = 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            statusText = "Draft cleared";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (getChars(key).length() > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (key == pendingKey && now - lastTapTime < tapDelay) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  tapCount++;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (tapCount > getChars(key).length()) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tapCount = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                finishCharacter();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      pendingKey = key;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            tapCount = 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    lastTapTime = now;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        statusText = "Typing";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              void setup() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.begin(115200);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  pinMode(TOUCH_SCL, OUTPUT);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    pinMode(TOUCH_SDO, INPUT);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      digitalWrite(TOUCH_SCL, HIGH);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Wire.begin(OLED_SDA, OLED_SCL);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              while (true) delay(100);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  showScreen();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    SPI.begin(18, 19, 23, LORA_SS);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      LoRa.setPins(LORA_SS, LORA_RST, LORA_DIO0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!LoRa.begin(LORA_FREQ)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            statusText = "LoRa failed";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    while (true) delay(100);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        LoRa.setSyncWord(0x12);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          LoRa.setSpreadingFactor(12);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            LoRa.setSignalBandwidth(125E3);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              LoRa.setCodingRate4(8);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                LoRa.setTxPower(10);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  LoRa.receive();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    statusText = "Ready";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      void loop() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        receiveMessage();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          int key = readTouchKey();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (key == 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                keyLatched = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else if (!keyLatched) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      keyLatched = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          handleTouchKey(key);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (pendingKey != 0 && millis() - lastTapTime >= tapDelay) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  finishCharacter();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      statusText = "Typing";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          showScreen();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              delay(10);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
